"""SWAM operations"""
import time
from taf.ul.trs_e2e_fw.lib.ems.exceptions import FailedToGetModulesException, FailedToGetReportException
from taf.ul.trs_e2e_fw.lib.ems.netact.netact_base import NetactBase
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from zeep import helpers as zeep_helpers

logger = BackgroundLogger.Instance()


class SWAM(NetactBase):

    def __init__(self):
        super(SWAM, self).__init__()

    def generate_reports(self, **kwargs):
        """
        Generate SWAM reports and wait for generation to complete.

        @Param kwargs:
            detailed (bool) - If False - only general information about the modules will be returned.
            module_name (string) - Expected module name='moduleName1' to generate reports.
            #filters (**) - Expected module attributes e.g. measurementType='CM',moduleName='moduleName1'.
            recheck_interval (int) - Interval between checking report generation task status.
            max_retries (int) - Maximum number of rechecks.
            trigger (string) - Allowed values: GENERATE_REPORT_TASK, LICENSE_MANAGER_NOTIFICATION,
                HARDLOCK_SCHEDULER_TASK, GENERATE_REPORT_REMOTE_SERVICE, GRACE_PERIOD_CAPACITY_CHANGED, HASH_FAIL,
                GENERATE_REPORT_ON_DEMAND.
            day (int|string|datetime.date) - Day or day indicating the end of period that has to be covered in
                report. Allowed values: 0 for today, -1 for yesterday and so on (the NetAct time zone is included) or
                YYYY-mm-dd e.g. 2020-02-20.
            alias (string) - Netact instance name. Default value is 'default'.

        Returns:
            reports generation status

        Return type:
            dict
        """

        detailed = kwargs.pop('detailed', True)
        recheck_interval = kwargs.pop('recheck_interval', 20)
        max_retries = kwargs.pop('max_retries', 20)
        trigger = kwargs.pop('trigger', 'GENERATE_REPORT_ON_DEMAND')
        day = kwargs.pop('day', 0)
        alias = kwargs.pop('alias', 'default')
        module_name = kwargs["module_name"]

        try:
            module = self._get_modules(detailed=detailed, alias=alias, moduleName=module_name)[0]
        except Exception as get_mod_exception:
            raise FailedToGetModulesException(
                "Failed to get modules with requested filters because of the error: {}".format(str(get_mod_exception)))
        else:
            report_dict = self.netact_factory.netact.generate_reports(module=module, recheck_interval=recheck_interval,
                                                                      max_retries=max_retries, trigger=trigger,
                                                                      day=day, alias=alias)
            report_dict = zeep_helpers.serialize_object(report_dict, dict)

            expected_keys = ["dailyReportId", "detailedReportId", "aggregatedReportId", "summaryReportId"]

            # wait for dictionary to be ready
            time.sleep(15)

            for retry_count in range(10):
                try:
                    for keys in report_dict:
                        if keys not in expected_keys:
                            report_dict.pop(keys)
                    return report_dict
                except Exception as report_e:
                    if retry_count == 9:
                        raise Exception("Retried to access generated report 10 times. {}.".format(str(report_e)))
                    elif str(report_e) == "dictionary changed size during iteration":
                        logger.debug("Failed to access report because: {0}\nRetrying count: {1}".format(str(
                            report_e), str(retry_count + 1)))
                        time.sleep(2)
                    else:
                        raise report_e

    def get_report(self, **kwargs):
        """
        get_report(report_id, alias=None)
            Get detailed SWAM report specified by given report_id.

        *Param kwargs:
            report_id (int) - dailyReportId, detailedReportId, aggregatedReportId or summaryReportId attribute of
            report generation status obtained using generate_reports functionality.
            alias (string) - Netact instance name. Default value is 'default'.

        Returns: report

        Return type: dict
        """
        report_id = kwargs['report_id']
        alias = kwargs.pop('alias', 'default')

        try:
            report = self.netact_factory.netact.get_report(report_id, alias=alias)
            report = zeep_helpers.serialize_object(report, dict)
        except Exception as report_e:
            raise FailedToGetReportException("Failed to get report with report id: {0}, due to error: {1}".format(
                str(report_id), str(report_e)))

        return report

    def _get_modules(self, **kwargs):
        """
        get_modules(detailed=True, alias=None, **filters)
            Get SWAM modules specified by given filters. Example output (detailed=True):

        @Param kwargs:
            detailed (bool) - If False - only general information about the modules will be returned.
            alias (string) - Netact instance name. Default value is 'default'.
            filters (**) - Expected module attributes e.g. measurementType='CM'.
        Returns: modules

        Return type: list(dict)
        """

        detailed = kwargs.pop('detailed', True)
        alias = kwargs.pop('alias', 'default')
        return self.netact_factory.netact.get_modules(detailed=detailed, alias=alias, **kwargs)

    def get_realizedvalue_and_licensecapacity_from_report(self, **kwargs):
        """
        Get Realizedvalue And Licensecapacity From Report

        This KW verifies if there is an entry with given parameters in the mentioned report and returns
        realizedValue(newBase) and licensedCapacity(capacity).
        @Param kwargs:

            report (dictionary) - Can be generated using get_report() functionality.
            module_name (string) - module name.
            distinguished_name (string) - distinguished name to search for in report.
            invoicing_sales_item (string) - invoicing_sales_item to be searched for in report.

        Returns: dict with realizedValue and licensedCapacity values

        return value: dict

        """
        report = kwargs['report']
        module_name = kwargs['module_name']
        target = kwargs['distinguished_name']
        sales_item_name = kwargs['invoicing_sales_item']
        all_key_value_pair = report.items()
        report_checklist = ('moduleName', module_name)
        rows_checklist = [('target', target), ('salesItemName', sales_item_name)]
        if report_checklist not in all_key_value_pair:
            raise Exception("{} was not found in the report.".format(report_checklist[0]))

        for rows in report['rows']:
            row_key_value_pair = rows.items()
            items_found = 0
            for row_pair in rows_checklist:
                if row_pair in row_key_value_pair:
                    items_found = items_found + 1
                else:
                    items_found = items_found - 1
            if items_found == 2:
                return {"realized_value": int(rows["newBase"]), "licensed_capacity": int(rows["capacity"])}

        raise Exception("Items, distinguished_name and invoicing_sales_item were not found together in any of the "
                        "rows in the report.")

    def wait_for_reports(self, **kwargs):
        """
        wait_for_reports(task_id, recheck_interval=20, max_retries=6, alias=None)
        Wait for SWAM reports generation task specified by given ID to complete.

        @Param kwargs:
            task_id (int) - Can be obtained using start_report_generation.
            recheck_interval (int) - Interval between checking report generation task status.
            max_retries (int) - Maximum number of rechecks.
            alias (string) - Netact instance name. Default value is 'default'.

        Returns: reports generation status (example output in generate_reports).

        Return type: dict
        """
        task_id = kwargs['task_id']
        recheck_interval = kwargs.pop('recheck_interval', 20)
        max_retries = kwargs.pop('max_retries', 6)
        alias = kwargs.pop('alias', 'default')

        return self.netact_factory.netact.wait_for_reports(task_id, recheck_interval=recheck_interval,
                                                           max_retries=max_retries, alias=alias)

    def start_reports_generation(self, **kwargs):
        """
        start_reports_generation(module, trigger='GENERATE_REPORT_ON_DEMAND', day=0, alias=None)
            Start SWAM reports generation asynchronously.

        @Param kwargs:
            module (dict) - Module for report generation (can be obtained using get_modules).
            trigger (string) - Allowed values: GENERATE_REPORT_TASK, LICENSE_MANAGER_NOTIFICATION,
                HARDLOCK_SCHEDULER_TASK, GENERATE_REPORT_REMOTE_SERVICE, GRACE_PERIOD_CAPACITY_CHANGED, HASH_FAIL,
                GENERATE_REPORT_ON_DEMAND.
            day (int|string|datetime.date) - Day or day indicating the end of period that has to be covered in
                report. Allowed values: 0 for today, -1 for yesterday and so on (the NetAct time zone is
                included) or YYYY-mm-dd e.g. 2020-02-20.
            alias (string) - Netact instance name. Default value is 'default'.

        Returns:
            task id

        Return type:
            int
        """

        module = kwargs['module']
        trigger = kwargs.pop('trigger', 'GENERATE_REPORT_ON_DEMAND')
        day = kwargs.pop('day', 0)
        alias = kwargs.pop('alias', 'default')

        return self.netact_factory.netact.start_reports_generation(module, trigger=trigger, day=day, alias=alias)

    def get_reports(self, **kwargs):
        """
        get_reports(module=None, start_day=None, end_day=None, detailed=False, alias=None, **filters)
            Get SWAM reports specified by given module or filters.

        @Param kwargs:
            module (dict) - Can be obtained using get_modules.
            start_day (string|datetime.date) - String in YYYY-mm-dd format e.g. 2020-02-20.
            end_day (string|datetime.date) - String in YYYY-mm-dd format e.g. 2020-02-20.
            detailed (bool) - If True - reports with 'rows' will be returned (example output in get_report).
            alias (string) - Netact instance name. Default value is 'default'.
            **filters - Expected report attributes e.g. measurementType='CM' :return: reports :rtype: list(dict)

        Returns: report of the requested module

        Return type: dict
        """

        module = kwargs.pop('module')
        start_day = kwargs.pop('start_day', None)
        end_day = kwargs.pop('end_day', None)
        detailed = kwargs.pop('detailed', False)
        alias = kwargs.pop('alias', 'default')
        return self.netact_factory.netact.get_reports(module=module, start_day=start_day, end_day=end_day,
                                                      detailed=detailed, alias=alias, **kwargs)
